// lib/utils.ts
import { type ClassValue, clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// Usage example
const buttonClass = cn(
  "px-4 py-2 bg-blue-500", // base classes
  variant === "large" && "px-6 py-3", // conditional classes
  className // allow overrides
);

// Common responsive patterns
const responsiveClasses = {
  // Text sizes
  heading: "text-2xl sm:text-3xl md:text-4xl lg:text-5xl",
  subheading: "text-lg sm:text-xl md:text-2xl",
  body: "text-sm sm:text-base",

  // Spacing
  section: "py-8 sm:py-12 md:py-16 lg:py-20",
  container: "px-4 sm:px-6 lg:px-8",

  // Grid layouts
  cardGrid: "grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 sm:gap-6",
  autoGrid: "grid grid-cols-[repeat(auto-fit,minmax(280px,1fr))] gap-6"
};
